  FT["PH-H9169"] = {"id":"PH-H9169","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2015/ra_10720_2015.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Sta. Marcela National High School–consuelo Annex in Barangay Consuelo, Municipality of Sta. Marcela, Province of Apayao From the Sta. Marcela National High School, Converting It Into An Independent National High School to Be Known as Consuelo National High School and Appropriating Funds Therefor","orig":"An Act Separating the Sta. Marcela National High School–consuelo Annex in Barangay Consuelo, Municipality of Sta. Marcela, Province of Apayao From the Sta. Marcela National High School, Converting It Into An Independent National High School to Be Known as Consuelo National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10720","issuingBody":"Congress of the Philippines","promulgatedDate":"2015-12-29","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2015/ra_10720_2015.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9169-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The Sta. Marcela National High School – Consuelo Annex in Barangay Consuelo, Municipality of Sta. Marcela, Province of Apayao is hereby separated from the Sta. Marcela National High School and converted into an independent national high school to be known as Consuelo National High School."}},{"id":"PH-H9169-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, assets, liabilities and records of the Sta. Marcela National High School – Consuelo Annex are hereby transferred to and absorbed by the Consuelo National High School."}},{"id":"PH-H9169-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Consuelo National High School, the initial funding of which shall be charged against the current year’s appropriation of the Sta. Marcela National High School – Consuelo Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H9169-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H9169-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p130"};
